with kept_keys as (select id from shipments intersect select id from shipments where carrier = 'Kerry'), kept_rows as (select s.* from shipments s join kept_keys k on s.id = k.id), base as (select *, datediff(shipped_date, delivered_date) as days_delivered_date_to_shipped_date, ceil(cost) as cost_whole from kept_rows where shipped_date > date '2023-07-16' and carrier is not distinct from 'Flash'), enriched as (select src.*, o.order_date, o.amount from base src left join orders o on src.order_id <=> o.id), enriched_shipments as (select a.*, d.channel, d.shipping_fee, d.amount as order_amount from enriched a left join orders d on a.order_id = d.id), joined as (select s.*, d.channel as order_channel, d.amount as order_amount_2, d.status as order_status from enriched_shipments s join orders d on s.order_id = d.id where d.customer_id in (1, 7, 18, 20)), scored as (select *, cume_dist() over (partition by order_status order by order_amount desc nulls last) as order_amount_cume_dist, dense_rank() over (order by amount nulls first) as amount_dense_rank, avg(order_amount_2) over (partition by order_channel) as order_channel_avg_order_amount_2 from joined), matched as (select a.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from scored a left join promotions pr on a.channel = pr.channel and a.delivered_date >= pr.starts_on and a.delivered_date < pr.ends_on + interval 14 days) select date_trunc('week', shipped_date) as week_start, count(distinct status) as distinct_status, percentile_approx(order_channel_avg_order_amount_2, array(0.25, 0.5, 0.75)) as order_channel_avg_order_amount_2_quartiles, count(distinct order_status) as distinct_order_status from matched group by date_trunc('week', shipped_date) order by week_start nulls last
